package com.shopwebsite.user;
import org.springframework.boot.SpringApplication;import org.springframework.boot.autoconfigure.SpringBootApplication;import org.springframework.context.annotation.Bean;import org.springframework.boot.CommandLineRunner;import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;
@SpringBootApplication public class UserServiceApplication { public static void main(String[] args){SpringApplication.run(UserServiceApplication.class,args);} @Bean CommandLineRunner seed(UserRepository repo){return args->{if(repo.findByEmailIgnoreCase("admin@shop.local").isEmpty())repo.save(new User("Store Admin","admin@shop.local",new BCryptPasswordEncoder().encode("admin123"),"ADMIN"));if(repo.findByEmailIgnoreCase("demo@shop.local").isEmpty())repo.save(new User("Demo Customer","demo@shop.local",new BCryptPasswordEncoder().encode("demo123"),"CUSTOMER"));};} }
